        if (s.size() < 3) return 0;
        int w = 0;
        for (size_t i = 1; i + 1 < s.size(); ++i) {
            int prev_d = s[i - 1] - '0';
            int cur_d = s[i] - '0';
            int next_d = s[i + 1] - '0';
            if ((cur_d > prev_d && cur_d > next_d) || (cur_d < prev_d && cur_d < next_d)) {
